/// Concatenate `a` followed by `b`.
///
/// Postconditions (informal):
/// - `c.len() == a.len() + b.len()`
/// - For all `i < a.len()`: `c[i] == a[i]`
/// - For all `i < b.len()`: `c[a.len() + i] == b[i]`
///
/// Termination:
/// - The implementation performs two finite loops over `a` and `b`,
///   so it always terminates.
pub fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Allocate exactly enough space so pushes won't reallocate.
    let mut c = Vec::with_capacity(a.len() + b.len());

    // After this loop: c == a (elementwise) and c.len() == a.len().
    for x in a.iter() {
        c.push(*x);
    }

    // After this loop: c == a followed by b, and c.len() == a.len() + b.len().
    for x in b.iter() {
        c.push(*x);
    }

    c
}

